<div class="d-flex justify-content-between align-items-center mb-4"><h1 class="h3 mb-0">Licencje</h1><div class="d-flex gap-2"><a href="/admin/licenses/export" class="btn btn-outline-secondary">Eksport CSV</a><a href="/admin/licenses/create" class="btn btn-primary">Generator licencji</a></div></div>
<?php if (!empty($_SESSION['_generated_licenses'])): $generated = $_SESSION['_generated_licenses']; unset($_SESSION['_generated_licenses']); ?><div class="alert alert-info"><strong>Wygenerowane klucze:</strong><ul class="mb-0 mt-2"><?php foreach ($generated as $item): ?><li><code><?= e($item['plain_key']) ?></code> <span class="text-muted">(panel: <?= e($item['masked_key']) ?>)</span></li><?php endforeach; ?></ul></div><?php endif; ?>
<div class="card shadow-sm mb-4"><div class="card-body"><form method="get" class="row g-3"><div class="col-md-3"><label class="form-label">Produkt</label><select name="product_id" class="form-select"><option value="">Wszystkie</option><?php foreach ($products as $product): ?><option value="<?= e((string) $product['id']) ?>" <?= (($filters['product_id'] ?? '') == $product['id']) ? 'selected' : '' ?>><?= e($product['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-2"><label class="form-label">Status</label><select name="status" class="form-select"><option value="">Wszystkie</option><?php foreach (['active','inactive','expired','revoked','suspended'] as $status): ?><option value="<?= e($status) ?>" <?= (($filters['status'] ?? '') === $status) ? 'selected' : '' ?>><?= e($status) ?></option><?php endforeach; ?></select></div><div class="col-md-2"><label class="form-label">Domena</label><input name="domain" class="form-control" value="<?= e($filters['domain'] ?? '') ?>"></div><div class="col-md-2"><label class="form-label">E-mail</label><input name="customer_email" class="form-control" value="<?= e($filters['customer_email'] ?? '') ?>"></div><div class="col-md-2"><label class="form-label">Fragment klucza</label><input name="key_fragment" class="form-control" value="<?= e($filters['key_fragment'] ?? '') ?>"></div><div class="col-md-1 d-flex align-items-end"><button class="btn btn-outline-primary w-100">Filtruj</button></div></form></div></div>
<div class="card shadow-sm"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>ID</th><th>Produkt</th><th>Klucz</th><th>Status</th><th>E-mail</th><th>Aktywacje</th><th>Wygasa</th><th></th></tr></thead><tbody><?php foreach ($licenses as $license): ?><tr><td><?= e((string) $license['id']) ?></td><td><?= e($license['product_name']) ?></td><td><code><?= e($license['masked_key']) ?></code></td><td><?= e($license['status']) ?></td><td><?= e($license['customer_email']) ?></td><td><?= e((string) $license['activations_in_use']) ?> / <?= e((string) $license['activation_limit']) ?></td><td><?= e($license['expires_at']) ?></td><td><a href="/admin/licenses/<?= e((string) $license['id']) ?>" class="btn btn-sm btn-outline-primary">Szczegóły</a></td></tr><?php endforeach; ?></tbody></table></div></div>
